const ids=['nome_loja','email_contacto','telefone_loja','pais_base'];async function load(){const d=await apiFetch('/operacoes/admin/configuracoes');ids.forEach(k=>{document.getElementById(k).value=d[k]||''})}document.getElementById('save').onclick=async()=>{try{const d={};ids.forEach(k=>d[k]=document.getElementById(k).value);await apiFetch('/operacoes/admin/configuracoes',{method:'PUT',body:JSON.stringify(d)});msg.textContent='Configurações guardadas.'}catch(e){msg.textContent=e.message}};load().catch(e=>msg.textContent=e.message);
